def find_rects(g, val):
    H,W=len(g),len(g[0]); seen=set(); rects=[]
    for i in range(H):
        for j in range(W):
            if g[i][j]==val and (i,j) not in seen:
                stack=[(i,j)]; comp=[]; seen.add((i,j))
                while stack:
                    a,b=stack.pop(); comp.append((a,b))
                    for da,db in ((1,0),(-1,0),(0,1),(0,-1)):
                        x,y=a+da,b+db
                        if 0<=x<H and 0<=y<W and g[x][y]==val and (x,y) not in seen:
                            seen.add((x,y)); stack.append((x,y))
                rs=[a for a,b in comp]; cs=[b for a,b in comp]
                r1,r2,c1,c2=min(rs),max(rs),min(cs),max(cs)
                h,w=r2-r1+1,c2-c1+1
                # check full border and interior only val or 0
                ok=True
                if h<3 or w<3: ok=False
                for a in range(r1,r2+1):
                    for b in range(c1,c2+1):
                        if a in (r1,r2) or b in (c1,c2):
                            if g[a][b]!=val: ok=False
                        else:
                            if g[a][b]!=0: ok=False
                rects.append((r1,r2,c1,c2,ok,len(comp)))
    return rects
